/**
 * A place and an area through generation.
 *
 * `column.place` and `column.area` are overlaid onto the model by whoever
 * composes a page (the server, from the column's rules; `modelFromRequiredSchema`,
 * from an app's manifest). From there the generator must hand both to the
 * rules: the place is listed and offered a map, the area keeps a field and no
 * column. The same table with no rule is generated byte for byte as before —
 * `generate-baseline.test.ts` pins that for a whole schema; this pins it for
 * the columns in question.
 */
import { describe, expect, it } from 'vitest';

import { composeRequestedPage, generatePages, modelFromRequiredSchema, parseDatabaseModel, type PageEnvelope } from '../src/index.js';

const CONN = 'conn_01HZX0000000000000000000';

function model(rules: boolean, logicalType: 'json' | 'text' = 'json') {
  return parseDatabaseModel({
    dialect: logicalType === 'json' ? 'postgres' : 'sqlite',
    name: 'depot',
    source: { kind: 'live', connectionId: CONN },
    tables: [
      {
        name: 'sites',
        columns: [
          { name: 'id', logicalType: 'integer', isPrimaryKey: true, nullable: false, default: { kind: 'autoincrement' } },
          { name: 'name', logicalType: 'varchar', nullable: false, maxLength: 80 },
          { name: 'spot', logicalType, ...(rules ? { place: true } : {}) },
          { name: 'zone', logicalType, ...(rules ? { area: true } : {}) },
          { name: 'notes', logicalType: 'json' },
        ],
        primaryKey: ['id'],
      },
    ],
  });
}

interface Spec {
  name: string;
  logicalType: string;
  hidden?: boolean;
  sortable?: boolean;
}
const columnsOf = (page: PageEnvelope | Record<string, unknown>): Spec[] => (page as unknown as { config: { columns: Spec[] } }).config.columns;
const crudOf = (pages: PageEnvelope[]): PageEnvelope => pages.find((page) => page.template === 'page-crud' && (page.source.table ?? '').endsWith('.sites'))!;

describe.each(['json', 'text'] as const)('a place and an area kept as %s', (logicalType) => {
  it('lists the place and keeps the area for the form on the generated records page', () => {
    const columns = columnsOf(crudOf(generatePages(model(true, logicalType), { connectionId: CONN }).pages));
    expect(columns.filter((column) => column.hidden !== true).map((column) => column.name)).toEqual(['name', 'spot']);
    expect(columns.find((column) => column.name === 'spot')).toMatchObject({ logicalType: 'json', sortable: false });
    expect(columns.find((column) => column.name === 'zone')).toMatchObject({ logicalType: 'json', sortable: false, hidden: true });
    expect(columns.some((column) => column.name === 'notes')).toBe(false);
  });

  it('does the same on a page composed on request', () => {
    const table = model(true, logicalType).tables[0]!.id;
    const built = composeRequestedPage(model(true, logicalType), table, 'page-crud', { connectionId: CONN, slug: 'sites', id: 'page_sites', navGroup: 'library', navIcon: 'list', navOrder: 1 });
    expect(built.envelope).not.toBeNull();
    const columns = columnsOf(built.envelope!);
    expect(columns.filter((column) => column.hidden !== true).map((column) => column.name)).toEqual(['name', 'spot']);
    expect(columns.find((column) => column.name === 'zone')?.hidden).toBe(true);
  });
});

describe('the same table with no rule', () => {
  it('leaves its json columns out, as before', () => {
    const columns = columnsOf(crudOf(generatePages(model(false), { connectionId: CONN }).pages));
    expect(columns.map((column) => column.name)).toEqual(['name', 'id']);
  });
});

describe('an app manifest that declares a place and an area', () => {
  it('models both rules on the columns, so its own check composes what the install will', () => {
    const manifest = {
      requiredSchema: {
        tables: [
          {
            ref: 'sites',
            columns: [
              { ref: 'id', type: 'int', role: 'pk' },
              { ref: 'name', type: 'text', maxLength: 80 },
              { ref: 'spot', type: 'json', nullable: true, rules: { place: true as const } },
              { ref: 'zone', type: 'json', nullable: true, rules: { area: true as const } },
              { ref: 'notes', type: 'json', nullable: true },
            ],
          },
        ],
      },
    };
    const sites = modelFromRequiredSchema(manifest).tables[0]!;
    const column = (name: string) => sites.columns.find((one) => one.name === name)!;
    expect(column('spot').place).toBe(true);
    expect(column('zone').area).toBe(true);
    expect(column('notes').place).toBeUndefined();
    expect(column('notes').area).toBeUndefined();
  });
});
